function generatePm2Config({ appName, script = 'server.js', instances = 'max', maxMemory = '500M', port = 3000 }) {
  return `// PM2 Cluster Mode Production Configuration
// Generated by vps-deploy-orchestrator

module.exports = {
  apps: [
    {
      name: '${appName}',
      script: '${script}',
      instances: '${instances}',
      exec_mode: 'cluster',
      autorestart: true,
      watch: false,
      max_memory_restart: '${maxMemory}',
      env_production: {
        NODE_ENV: 'production',
        PORT: ${port}
      }
    }
  ]
};
`;
}

module.exports = { generatePm2Config };
